"""Writes the generated tables of the crate from the generated files of the Go port (which are written from the
.NET sources): src/names.rs (tag names), src/attr_names.rs (attribute names) and src/entities.rs (HTML5 named
character references).

    python tools/gen.py ../fasthtmlparser
"""

import re
import sys
from pathlib import Path


def go_string(literal: str) -> str:
    """Decodes a Go interpreted string literal (without the quotes)."""
    out = []
    i = 0
    while i < len(literal):
        c = literal[i]
        if c != "\\":
            out.append(c)
            i += 1
            continue
        e = literal[i + 1]
        if e == "u":
            out.append(chr(int(literal[i + 2 : i + 6], 16)))
            i += 6
        elif e == "U":
            out.append(chr(int(literal[i + 2 : i + 10], 16)))
            i += 10
        elif e == "x":
            out.append(chr(int(literal[i + 2 : i + 4], 16)))
            i += 4
        else:
            out.append({"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\", "'": "'"}[e])
            i += 2
    return "".join(out)


def rust_string(s: str) -> str:
    out = []
    for c in s:
        if c in '"\\':
            out.append("\\" + c)
        elif 0x20 <= ord(c) < 0x7F:
            out.append(c)
        else:
            out.append("\\u{%x}" % ord(c))
    return '"' + "".join(out) + '"'


def upper_snake(camel: str) -> str:
    return re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", camel).upper()


HEADER = "// Code generated by tools/gen.py; DO NOT EDIT.\n\n"


def tags(go: Path) -> str:
    text = (go / "names_gen.go").read_text(encoding="utf-8")
    consts = re.findall(r"^\tTag(\w+)(?: Tag = iota)?$", text, re.M)
    names = [go_string(s) for s in re.findall(r'^\t"((?:[^"\\]|\\.)*)",$', text[text.index("var tagNames") :], re.M)]
    assert len(consts) == len(names), (len(consts), len(names))
    b = [HEADER, "use crate::Tag;\n\n"]
    b.append("/// Known tag names: HTML (incl. obsolete), SVG, MathML and common XML (RSS, Atom, sitemap).\n")
    b.append("/// Any other name works as a string (`by_name(\"my-widget\")`).\n")
    b.append("impl Tag {\n")
    for i, (c, n) in enumerate(zip(consts, names)):
        b.append(f"    /// `{n}`\n    pub const {upper_snake(c)}: Tag = Tag({i});\n")
    b.append("}\n\n")
    b.append(f"pub(crate) const TAG_COUNT: usize = {len(names)};\n\n")
    b.append("/// The lower-case tag names, indexed by `Tag`.\n")
    b.append("pub(crate) static TAG_NAMES: [&str; TAG_COUNT] = [\n")
    for n in names:
        b.append(f"    {rust_string(n)},\n")
    b.append("];\n")
    return "".join(b)


def attributes(go: Path) -> str:
    text = (go / "attributes_gen.go").read_text(encoding="utf-8")
    pairs = re.findall(r'^\tAttr(\w+)\s*=\s*"((?:[^"\\]|\\.)*)"$', text, re.M)
    b = [HEADER]
    b.append("//! Common HTML / SVG / XML attribute names, for `attr`, `attr_raw`, `Query::attr` and the shortcuts.\n")
    b.append("//! Any other name works as a plain string.\n\n")
    for c, v in pairs:
        b.append(f"/// `{go_string(v)}`\npub const {upper_snake(c)}: &str = {rust_string(go_string(v))};\n")
    return "".join(b)


def entities(go: Path) -> str:
    text = (go / "entities_gen.go").read_text(encoding="utf-8")
    rows = re.findall(r'^\t"(\w+)":\s*\{"((?:[^"\\]|\\.)*)", (true|false)\},$', text, re.M)
    max_name = int(re.search(r"entityMaxName\s*=\s*(\d+)", text).group(1))
    max_legacy = int(re.search(r"entityMaxLegacyName\s*=\s*(\d+)", text).group(1))
    rows.sort(key=lambda r: r[0].encode())
    b = [HEADER]
    b.append("/// HTML5 named character references (without '&' and ';'), sorted by name; legacy ones are also\n")
    b.append("/// recognized without ';'.\n")
    b.append(f"pub(crate) static ENTITIES: [(&str, &str, bool); {len(rows)}] = [\n")
    for name, value, legacy in rows:
        b.append(f"    ({rust_string(name)}, {rust_string(go_string(value))}, {legacy}),\n")
    b.append("];\n\n")
    b.append(f"pub(crate) const ENTITY_MAX_NAME: usize = {max_name};\n")
    b.append(f"pub(crate) const ENTITY_MAX_LEGACY_NAME: usize = {max_legacy};\n")
    return "".join(b)


def main() -> None:
    go = Path(sys.argv[1] if len(sys.argv) > 1 else "../fasthtmlparser")
    src = Path(__file__).resolve().parent.parent / "src"
    for name, content in (("names.rs", tags(go)), ("attr_names.rs", attributes(go)), ("entities.rs", entities(go))):
        (src / name).write_text(content, encoding="utf-8", newline="\n")
        print("wrote", src / name)


if __name__ == "__main__":
    main()
